using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Observer.ProbabilisticClosure.TrajectoryLaws.Rectangles;

internal sealed class AsymmetricObservationLimitsDocument : IScribeDocumentDefinition
{
    private static DocumentBlock.Describe Entry(string id, string selector, string title, string text, DescribeRole role) =>
        Describe.Lean(DescribeId.Create(id),
            DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/Rectangles/AsymmetricObservationLimits." + selector),
            H(title), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text(text))), role);

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Actual asymmetric observation limits", H("Actual asymmetric observation limits"),
        Blocks(
            Entry("observation", "observation", "Independent chronological observation lengths",
                "For an integer-indexed Boolean path z and natural lengths l and r, observation(l,r,z) is the pair of the original chronological leftWord(l,z), on coordinates minus l through minus one, and rightWord(r,z), on coordinates one through r. The center is absent. Either length can be zero.", DescribeRole.Definition),
            Entry("mean", "mean", "The actual conditional probability under one law",
                "For a probability measure mu on visible paths and a measurable observation o, mean(mu,o,z) evaluates the actual conditional distribution of z(0) given o at o(z), on the event that the center bit is true. The total conditional kernel supplies values even at null observation fibers. No limiting posterior is defined through an inequality or an inverse construction.", DescribeRole.Definition),
            Entry("mean-square-limit", "MeanSquareLimit", "Almost-sure and L2 convergence",
                "MeanSquareLimit(mu,f,g) asserts almost-sure pointwise convergence of f(n) to g, membership of every f(n) and g in L2(mu), and convergence to zero of the integral of the squared difference. All measures in these assertions are the same mu.", DescribeRole.Definition),
            Entry("ordered-limits", "ordered_half_line_limits", "Both orders of completing the retained half-lines",
                "For every probability mu on original integer-time visible paths and every natural retained length j, completing the left side of observation(k,n) converges almost surely and in L2 to the actual mean given the entire past and the first n future bits. Completing the right side of observation(n,k) converges in both senses to the actual mean given the last n past bits and the entire future. These two intermediate means, as n increases, each converge to the actual mean given the full exterior. With j fixed, observation(j,n) converges to the actual leftObservation(j) mean, and observation(n,j) to the actual rightObservation(j) mean. Thus both ordered completions retain exactly the source observation fields. For j zero, the opposite infinite half-line remains present. The proof reconstructs each infinite coordinate field from chronological finite observations, applies Levy upward convergence to the actual conditional expectations, and uses the uniform interval from zero to one to prove square-error convergence by dominated convergence. Finite and limiting means are explicitly in L2.", DescribeRole.Theorem),
            Entry("left-count", "leftCount", "The original blocks ending at minus one",
                "For a word w, block length b, retained length j and path z, leftCount is originalSuccessCount(w,b,j/b) on the chronological leftWord(j,z), after dropping the first j modulo b bits. Its full blocks are exactly the source intervals from minus q times b through minus one, where q is j/b. A full block contributes one if it contains any complete occurrence of w; overlapping occurrences in one block still contribute only one.", DescribeRole.Definition),
            Entry("right-count", "rightCount", "The original blocks starting at one",
                "rightCount is originalSuccessCount(w,b,j/b) on the chronological rightWord(j,z). Its full blocks start at one and each have length b. Neither count changes when observations outside the retained j bits are added.", DescribeRole.Definition),
            Entry("same-law-counted-bound", "same_law_counted_half_line_smoothing", "The original finite bound transfers to the full opposite half-line",
                "Let H be finite with measurable singletons, theta an original stationary binary edge presentation, and J any probability measure satisfying exactly theta's original marked-cylinder identities. Let w be nonempty and let its original word product have rectangular positive support R. Set mu to the visible pushforward of this same J, b to length(w) plus card(H), and rho to one minus the exact rectangleMinimum divided by rectangleMaximum. On one common mu-null-set convention, for every j, the absolute difference between the actual full-exterior mean and the actual leftObservation(j) mean is at most rho raised to leftCount(w,b,j,z); the corresponding rightObservation(j) difference is at most rho raised to rightCount(w,b,j,z). The frozen finite_record_smoothing_by_original_success_count supplies both finite comparisons unchanged. Actual finite observation fibers equal the original chronological record cylinders. Outside their actual null fibers, conditional disintegration gives precisely recordPosterior, so the finite comparisons apply to actual conditional expectations. First the extra side tends to infinity, then the common opposite side tends to infinity, with the original count fixed. Countable intersections give the common null-set convention. No independence, row unifilarity, aperiodicity, global entrywise no11, extra positivity or posterior band is assumed. Structural zeros and zero-probability fibers are allowed. Natural powers retain rho zero and count zero, with the zeroth power equal to one. In particular j zero retains its entire opposite half-line.", DescribeRole.Theorem),
            Paragraph(Text("For the positive-weight class C in the rectangular-word theorem, take H to be the original subtype C, theta to be nativeComponent, and J to be its original-cylinder law. component_restriction identifies its visible pushforward with the actual class-conditioned visible law. Keep the source w, its support rectangle, the exact minimum and maximum, and b equal to length(w) plus card(C). The two displayed inequalities are then the source full-half-line comparisons with the original block clocks. The theorem does not assert the separate explicit feasible-state kernel formulas, their common-mass minorization, or product telescoping identities. Nor does it establish chronological count-moment payment, risk summability, or the component-mixture tail conclusions.")))));
}
